import sailpoint.connector.DelimitedFileConnector;
import sailpoint.tools.Util;

Map map = DelimitedFileConnector.defaultBuildMap(cols, record);

String hierarchyType = map.get("HIERARCHY_TYPE");
String logicalName = map.get("LOGICAL_NAME");
String hierarchyType_logicalName = hierarchyType + "(" + logicalName + ")";

if(schema.getObjectType() != null && schema.getObjectType().equalsIgnoreCase("account")){
  if(!Util.isNullOrEmpty(hierarchyType) && !Util.isNullOrEmpty(logicalName)){
    map.put("HIERARCHY_TYPE(LOGICAL_NAME)",hierarchyType_logicalName);
  }
}else if(schema.getObjectType() != null && schema.getObjectType().equalsIgnoreCase("Logical Name")){
  if(!Util.isNullOrEmpty(hierarchyType) && !Util.isNullOrEmpty(logicalName)){
    map.put("HIERARCHY_TYPE(LOGICAL_NAME)",hierarchyType_logicalName);
  }
}

return map;
